// Classifica a mensagem que chegou. A 'etapa' do usuario NAO e guardada:
// ela vem carimbada no tipo da mensagem do WhatsApp.
const t = $('Quando chamado pelo Webhook').first().json;
const msg = t.message || {};
const contact = t.contact || {};
const rawFrom = msg.from || contact.wa_id || '';
const phone = String(rawFrom).replace(/\D/g, '');
const profileName = (contact.profile && contact.profile.name) || '';
const phoneNumberId = t.phone_number_id;

let kind = 'text';      // text | button | flow_complete
let buttonId = null;
let flowResponse = null;
const mtype = msg.type;

if (mtype === 'interactive' && msg.interactive) {
  const it = msg.interactive;
  if (it.type === 'nfm_reply' && it.nfm_reply) {
    kind = 'flow_complete';
    try { flowResponse = JSON.parse(it.nfm_reply.response_json || '{}'); } catch (e) { flowResponse = {}; }
  } else if (it.type === 'button_reply' && it.button_reply) {
    kind = 'button'; buttonId = it.button_reply.id || '';
  } else if (it.type === 'list_reply' && it.list_reply) {
    kind = 'button'; buttonId = it.list_reply.id || '';
  } else {
    kind = 'text'; // interactive desconhecido -> recomeca
  }
} else if (mtype === 'button' && msg.button) {
  kind = 'button'; buttonId = msg.button.payload || msg.button.text || '';
} else {
  kind = 'text'; // text, image, audio, sticker, location... -> inicio
}

if (!phone) throw new Error('Mensagem sem telefone do cliente (message.from / contact.wa_id)');
if (!phoneNumberId) throw new Error('Mensagem sem phone_number_id vindo do webhook');

const wamid = msg.id || '';
let text = '';
if (mtype === 'text' && msg.text) text = msg.text.body || '';

return [{ json: { phone, profileName, phoneNumberId, kind, buttonId, flowResponse, wamid, text, rawType: mtype || 'unknown' } }];

// Botao 'Fazer novo pedido' -> reabre o Flow do cardapio.
const c = $('Classificar Mensagem').first().json;
const cfg = $('Config Disparo').first().json;
const NL = String.fromCharCode(10);
let ctx = {};
try { ctx = $('Sessão Claim').first().json.context || {}; } catch (e) { ctx = {}; }
if (typeof ctx === 'string') { try { ctx = JSON.parse(ctx); } catch (e) { ctx = {}; } }
const openId = (ctx && ctx.open_order_id) ? ctx.open_order_id : '';
const accepted = !!(ctx && ctx.order_accepted);
const flowToken = 'aurora-rest-' + c.phone + '-' + Date.now();
const payload = {
  messaging_product: 'whatsapp', recipient_type: 'individual', to: c.phone, type: 'interactive',
  interactive: {
    type: 'flow',
    header: { type: 'text', text: 'Cardápio Aurora' },
    body: { text: 'Boa! Toque abaixo para montar seu novo pedido 🍔' + NL + NL + '💬 A qualquer momento, digite *menu* para ver suas opções.' },
    footer: { text: 'Grupo Aurora' },
    action: { name: 'flow', parameters: { flow_message_version: '3', flow_token: flowToken, flow_id: cfg.FLOW_ID, mode: cfg.FLOW_MODE, flow_cta: cfg.FLOW_CTA, flow_action: 'data_exchange' } }
  }
};
let followup = null;
if (openId) {
  const fb = [ { type: 'reply', reply: { id: 'status:' + openId, title: 'Status do pedido' } } ];
  if (accepted) fb.push({ type: 'reply', reply: { id: 'falar_atendente', title: 'Falar c/ atendente' } });
  followup = { messaging_product: 'whatsapp', recipient_type: 'individual', to: c.phone, type: 'interactive', interactive: { type: 'button', body: { text: 'Ou, se preferir, acompanhe seu pedido em aberto:' }, action: { buttons: fb } } };
}
return [{ json: { phoneNumberId: c.phoneNumberId, payload, followup, session: { context: { open_order_id: openId, order_accepted: accepted } } } }];

// Botao 'Falar com atendente' -> placeholder (sem coexistencia ainda).
const c = $('Classificar Mensagem').first().json;
const NL = String.fromCharCode(10);
const text = 'Logo logo um atendente assume por aqui 🙂' + NL + NL + 'Esse recurso ainda está em implantação. Enquanto isso, posso te ajudar a fazer um pedido — é só tocar no botão abaixo 👇';
const payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: c.phone, type: 'interactive', interactive: { type: 'button', body: { text }, action: { buttons: [ { type: 'reply', reply: { id: 'novo_pedido', title: 'Fazer novo pedido' } } ] } } };
return [{ json: { phoneNumberId: c.phoneNumberId, payload, session: { state: 'HUMAN' } } }];

// Mostra o status atual do pedido consultado, revalidando no Odoo.
const c = $('Classificar Mensagem').first().json;
let o = $input.first() ? $input.first().json : null;
if (o && o.data && !o.id) o = o.data; // caso a API embrulhe em {data:{...}}
if (Array.isArray(o)) o = o[0] || null;
const wanted = (c.buttonId || '').split(':')[1];

// /customers/search retorna array; o HTTP node quebra em varios items.
let cItems = [];
try { cItems = $('Odoo Cliente (Status)').all().map((i) => i.json); } catch (e) { cItems = []; }
let custList = [];
if (cItems.length > 1) {
  custList = cItems;
} else {
  const f = cItems.length ? cItems[0] : null;
  if (Array.isArray(f)) custList = f;
  else if (f && Array.isArray(f.data)) custList = f.data;
  else if (f && (f.id || f.phone)) custList = [f];
  else custList = [];
}
const me = custList.find((x) => String(x.phone || '').replace(/\D/g, '') === c.phone) || custList[0] || null;

const STATES = { pending: 'aguardando o restaurante aceitar ⏳', draft: 'aceito, em preparo 👨\u200d🍳', out_for_delivery: 'saiu para entrega 🛵', paid: 'pago / finalizado ✅', rejected: 'recusado pelo restaurante ❌' };
const brl = (v) => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');

const hasOrder = o && o.id && o.state;
const ownerOk = hasOrder && o.partner_id && me && Number(o.partner_id.id) === Number(me.id);
const NL = String.fromCharCode(10);
const EXPLAIN = { pending: 'O restaurante ainda não aceitou. Assim que aceitarem o preparo, te aviso por aqui 🙂', draft: 'Seu pedido foi aceito e já está em preparo 🍳', out_for_delivery: 'Seu pedido saiu para entrega 🛵 chega já!', paid: 'Pedido finalizado. Bom apetite! 😋', rejected: 'Infelizmente o restaurante recusou o pedido 😕 Você pode tentar um novo pedido.' };

let text;
if (hasOrder && ownerOk) {
  const label = STATES[o.state] || ('status: ' + o.state);
  let detalhes = '';
  try { if (Array.isArray(o.lines) && o.lines.length) { detalhes = NL + NL + 'Itens:' + NL + o.lines.map((l) => '• ' + (l.qty || l.quantity || 1) + 'x ' + ((l.product_id && l.product_id.name) || l.full_product_name || l.name || 'item')).join(NL); } } catch (e) { detalhes = ''; }
  text = '📋 Pedido ' + (o.name || ('#' + o.id)) + NL + 'Status: ' + label + NL + (EXPLAIN[o.state] || '') + detalhes + NL + NL + 'Total: ' + brl(o.amount_total);
} else if (hasOrder && !ownerOk) {
  text = 'Esse pedido não está vinculado ao seu número 🤔\nSe quiser, toque em "Fazer novo pedido" para começar.';
} else {
  text = 'Não encontrei o pedido ' + (wanted ? '#' + wanted : '') + ' 🤔\nPode ser que já tenha sido finalizado. Quer fazer um novo pedido?';
}
const trackId = (hasOrder && ownerOk) ? o.id : '';
const accepted = hasOrder && ownerOk && ['pending', 'rejected'].indexOf(o.state) === -1;
const buttons = [];
if (trackId) buttons.push({ type: 'reply', reply: { id: 'status:' + trackId, title: 'Status do pedido' } });
buttons.push({ type: 'reply', reply: { id: 'novo_pedido', title: 'Fazer novo pedido' } });
if (accepted) buttons.push({ type: 'reply', reply: { id: 'falar_atendente', title: 'Falar c/ atendente' } });
const payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: c.phone, type: 'interactive', interactive: { type: 'button', body: { text }, action: { buttons: buttons.slice(0, 3) } } };
return [{ json: { phoneNumberId: c.phoneNumberId, payload, session: { context: { open_order_id: trackId, order_accepted: accepted } } } }];

// Avalia se o cliente existe na base do Odoo.
// A API /customers/search retorna um array; o HTTP node quebra o array em
// varios items, entao normalizamos $input.all() para uma unica lista.
const c = $('Classificar Mensagem').first().json;
const items = $input.all().map((i) => i.json);
let list = [];
if (items.length > 1) {
  list = items; // array quebrado em varios items
} else {
  const f = items.length ? items[0] : null;
  if (Array.isArray(f)) list = f;
  else if (f && Array.isArray(f.data)) list = f.data;
  else if (f && (f.id || f.phone)) list = [f]; // objeto unico de cliente
  else list = [];
}
const me = list.find((x) => String(x.phone || '').replace(/\D/g, '') === c.phone) || list.find((x) => x.active !== false) || list[0] || null;
return [{ json: { exists: !!me, customerId: me ? me.id : null, customerName: me ? me.name : '', phone: c.phone, phoneNumberId: c.phoneNumberId, profileName: c.profileName } }];

// Cliente existente: tem pedido aberto? -> menu de 3 botoes; senao -> abre o Flow.
// A API /orders retorna um array; o HTTP node quebra em varios items, entao
// normalizamos $input.all() para uma unica lista.
const a = $('Avalia Cliente').first().json;
const cfg = $('Config Disparo').first().json;
const items = $input.all().map((i) => i.json);
let orders = [];
if (items.length > 1) {
  orders = items;
} else {
  const f = items.length ? items[0] : null;
  if (Array.isArray(f)) orders = f;
  else if (f && Array.isArray(f.data)) orders = f.data;
  else if (f && f.id) orders = [f];
  else orders = [];
}
const CLOSED = ['rejected', 'cancel', 'cancelled', 'done', 'invoiced', 'paid'];
const open = orders.filter((o) => o.partner_id && Number(o.partner_id.id) === Number(a.customerId) && CLOSED.indexOf(o.state) === -1);
open.sort((x, y) => Number(y.id) - Number(x.id));
const firstName = String(a.customerName || a.profileName || '').split(' ')[0];

let payload;
let sessionHint = null;
if (open.length > 0) {
  const ord = open[0];
  const STATES = { pending: 'aguardando o restaurante aceitar ⏳', draft: 'aceito, em preparo 🍳', out_for_delivery: 'saiu para entrega 🛵', paid: 'finalizado ✅' };
  const accepted = ['pending', 'rejected'].indexOf(ord.state) === -1;
  const NL = String.fromCharCode(10);
  const brl = (v) => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');
  const statusLbl = STATES[ord.state] || ord.state;
  const bodyText = '📋 Você tem um pedido em aberto:' + NL + NL + (ord.name || ('#' + ord.id)) + NL + 'Status: ' + statusLbl + (ord.amount_total ? (NL + 'Total: ' + brl(ord.amount_total)) : '') + NL + NL + 'O que você quer fazer?';
  const mbtns = [
    { type: 'reply', reply: { id: 'status:' + ord.id, title: 'Status do pedido' } },
    { type: 'reply', reply: { id: 'novo_pedido', title: 'Fazer novo pedido' } }
  ];
  if (accepted) mbtns.push({ type: 'reply', reply: { id: 'falar_atendente', title: 'Falar c/ atendente' } });
  payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: a.phone, type: 'interactive', interactive: { type: 'button', body: { text: bodyText }, action: { buttons: mbtns } } };
  sessionHint = { context: { open_order_id: ord.id, order_accepted: accepted } };
} else {
  const flowToken = 'aurora-rest-' + a.phone + '-' + Date.now();
  payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: a.phone, type: 'interactive', interactive: { type: 'flow', header: { type: 'text', text: 'Cardápio Aurora' }, body: { text: 'Bem-vindo de volta, ' + (firstName || '') + '! 🍔 Toque abaixo para montar seu pedido.' + String.fromCharCode(10, 10) + '💬 A qualquer momento, digite *menu* para ver suas opções.' }, footer: { text: 'Grupo Aurora' }, action: { name: 'flow', parameters: { flow_message_version: '3', flow_token: flowToken, flow_id: cfg.FLOW_ID, mode: cfg.FLOW_MODE, flow_cta: cfg.FLOW_CTA, flow_action: 'data_exchange' } } } };
  sessionHint = { context: { open_order_id: '', order_accepted: false } };
}
return [{ json: { phoneNumberId: a.phoneNumberId, payload, session: sessionHint } }];

// Cliente novo: boas-vindas + abre o Flow. O cliente sera criado no Odoo ao gerar a ordem.
const a = $('Avalia Cliente').first().json;
const cfg = $('Config Disparo').first().json;
const flowToken = 'aurora-rest-' + a.phone + '-' + Date.now();
const nome = String(a.profileName || '').split(' ')[0];
const payload = {
  messaging_product: 'whatsapp', recipient_type: 'individual', to: a.phone, type: 'interactive',
  interactive: {
    type: 'flow',
    header: { type: 'text', text: 'Bem-vindo à Aurora 🍔' },
    body: { text: (nome ? ('Olá, ' + nome + '! ') : 'Olá! ') + 'Que bom ter você aqui 😄 Toque abaixo para ver o cardápio e fazer seu primeiro pedido.' + String.fromCharCode(10, 10) + '💬 A qualquer momento, digite *menu* para ver suas opções.' },
    footer: { text: 'Grupo Aurora' },
    action: { name: 'flow', parameters: { flow_message_version: '3', flow_token: flowToken, flow_id: cfg.FLOW_ID, mode: cfg.FLOW_MODE, flow_cta: cfg.FLOW_CTA, flow_action: 'data_exchange' } }
  }
};
return [{ json: { phoneNumberId: a.phoneNumberId, payload, session: { context: { open_order_id: '', order_accepted: false } } } }];

// Mensagem de fallback quando o Odoo falha (qualquer saida de erro).
const c = $('Classificar Mensagem').first().json;
const NL = String.fromCharCode(10);
const text = 'Tivemos uma instabilidade momentânea por aqui 🙏' + NL + 'Pode tentar de novo pelo botão abaixo 👇';
const payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: c.phone, type: 'interactive', interactive: { type: 'button', body: { text }, action: { buttons: [ { type: 'reply', reply: { id: 'novo_pedido', title: 'Fazer novo pedido' } } ] } } };
return [{ json: { phoneNumberId: c.phoneNumberId, payload } }];

const wh = $json;
const body = wh.body || {};
const secret = (wh.headers && wh.headers['x-webhook-secret']) || body.secret || '';
if (String(secret) !== String(wh.PUSH_SECRET || '')) return [];
const phone = String(body.phone || '').replace(/\D/g, '');
if (!phone) return [];
const NL = String.fromCharCode(10);
const orderId = body.order_id || body.id || '';
const ref = body.order_name || (orderId ? ('#' + orderId) : 'seu pedido');
const total = (body.amount_total != null && body.amount_total !== '') ? ('Total: R$ ' + Number(body.amount_total).toFixed(2).replace('.', ',')) : '';
let text;
if (wh.push_type === 'accepted') {
  text = '🎉 Boa notícia! Seu pedido ' + ref + ' foi aceito pelo restaurante e já está sendo preparado 🍳' + (total ? (NL + NL + total) : '') + NL + NL + 'Te aviso assim que sair para entrega 🛵';
} else {
  text = '🛵 Seu pedido ' + ref + ' saiu para entrega!' + (total ? (NL + NL + total) : '') + NL + NL + 'Já está a caminho — bom apetite! 😋';
}
const payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: phone, type: 'interactive', interactive: { type: 'button', body: { text }, action: { buttons: [ { type: 'reply', reply: { id: 'menu', title: 'Menu' } } ] } } };
const channel = String(wh.WA_PHONE_NUMBER_ID || '');
const Q = (s) => "'" + String(s == null ? '' : s).split("'").join("''") + "'";
const ctx = { open_order_id: orderId || '', order_accepted: true };
const va = JSON.stringify(['menu']);
const cj = JSON.stringify(ctx);
const saveSql = 'INSERT INTO wa_session (channel_id, phone, state, valid_actions, context, updated_at) VALUES (' + Q(channel) + ', ' + Q(phone) + ', ' + Q('ORDER_PLACED') + ', ' + Q(va) + '::jsonb, ' + Q(cj) + '::jsonb, now()) ON CONFLICT (channel_id, phone) DO UPDATE SET state = ' + Q('ORDER_PLACED') + ', valid_actions = ' + Q(va) + '::jsonb, context = wa_session.context || ' + Q(cj) + '::jsonb, updated_at = now();';
return [{ json: { phone, phoneNumberId: channel, payload, WA_TOKEN: wh.WA_TOKEN, GRAPH_VERSION: wh.GRAPH_VERSION, saveSql } }];

// flow_complete: o pedido foi montado no Flow e veio no nfm_reply.
// Aqui criamos o pedido no Odoo a partir do order_payload do Flow.
const c = $('Classificar Mensagem').first().json;
const fr = c.flowResponse || {};
let op = {};
try { op = (typeof fr.order_payload === 'string') ? JSON.parse(fr.order_payload || '{}') : (fr.order_payload || {}); } catch (e) { op = {}; }
const paymentType = (op.payment && op.payment.type) || '';
return [{ json: { phone: c.phone, phoneNumberId: c.phoneNumberId, orderPayload: op, paymentType, pagamento: fr.pagamento || '', total: fr.total || '', itens: fr.itens || '', entrega: fr.entrega || '' } }];

const p = $('Prep Pedido (Flow)').first().json;
const order = $input.first() ? $input.first().json : {};
const ref = (order && order.name && order.name !== '/') ? order.name : (order && order.id ? ('#' + order.id) : '');
const oid = (order && order.id) ? order.id : '';
const NL = String.fromCharCode(10);
const STATES = { pending: 'aguardando o restaurante aceitar ⏳', draft: 'aceito, em preparo 🍳', out_for_delivery: 'saiu para entrega 🛵', paid: 'finalizado ✅', rejected: 'recusado ❌' };
const st = (order && order.state) ? order.state : 'pending';
const statusLabel = STATES[st] || st;
const text = '✅ Pedido ' + ref + ' enviado ao restaurante!' + NL + NL + (p.total || '') + NL + NL + 'Status: ' + statusLabel + NL + NL + 'Assim que o restaurante aceitar o preparo, te aviso por aqui 🍔' + NL + NL + 'Toque em *Menu* para ver suas opções.';
const payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: p.phone, type: 'interactive', interactive: { type: 'button', body: { text }, action: { buttons: [ { type: 'reply', reply: { id: 'menu', title: 'Menu' } } ] } } };
return [{ json: { phoneNumberId: p.phoneNumberId, payload, session: { state: 'ORDER_PLACED', context: { open_order_id: oid, order_accepted: false } } } }];

const p = $('Prep Pedido (Flow)').first().json;
const NL = String.fromCharCode(10);
const text = '✅ Pedido recebido!' + NL + NL + (p.total || '') + NL + NL + '💳 Pagamento pendente — pague pelo link do Mercado Pago para confirmar o pedido.' + NL + NL + '🔗 (link de pagamento em breve)' + NL + NL + 'Assim que o pagamento for confirmado, seu pedido vai para a cozinha do restaurante 🍔';
const payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: p.phone, type: 'interactive', interactive: { type: 'button', body: { text }, action: { buttons: [ { type: 'reply', reply: { id: 'novo_pedido', title: 'Fazer novo pedido' } } ] } } };
return [{ json: { phoneNumberId: p.phoneNumberId, payload, session: { state: 'AWAITING_PAYMENT', context: { open_order_id: '', order_accepted: false } } } }];

const c = $('Classificar Mensagem').first().json;
const channel = String(c.phoneNumberId || '');
const phone = String(c.phone || '');
const wamid = String(c.wamid || ('nowamid-' + Date.now() + '-' + Math.floor(Math.random() * 1e9)));
const Q = (s) => "'" + String(s == null ? '' : s).split("'").join("''") + "'";
const claimSql = 'INSERT INTO wa_session (channel_id, phone, last_wamid) VALUES (' + Q(channel) + ', ' + Q(phone) + ', ' + Q(wamid) + ') ON CONFLICT (channel_id, phone) DO UPDATE SET last_wamid = EXCLUDED.last_wamid WHERE wa_session.last_wamid IS DISTINCT FROM EXCLUDED.last_wamid RETURNING state, valid_actions, context, EXTRACT(EPOCH FROM (now() - updated_at))::int AS idle_seconds;';
return [{ json: { claimSql, channel_id: channel, phone, wamid } }];

const c = $('Classificar Mensagem').first().json;
let sess = {};
try { sess = $('Sessão Claim').first().json || {}; } catch (e) { sess = {}; }
if (!('state' in sess)) return [];
const TTL = 2700;
let state = sess.state || 'IDLE';
let validActions = sess.valid_actions;
if (typeof validActions === 'string') { try { validActions = JSON.parse(validActions); } catch (e) { validActions = []; } }
if (!Array.isArray(validActions)) validActions = [];
let context = sess.context;
if (typeof context === 'string') { try { context = JSON.parse(context); } catch (e) { context = {}; } }
if (!context || typeof context !== 'object') context = {};
const idle = Number(sess.idle_seconds || 0);
if (idle > TTL) { state = 'IDLE'; validActions = []; }
const RESET = ['oi', 'ola', 'olá', 'menu', 'inicio', 'início', 'comecar', 'começar', 'recomecar', 'recomeçar', 'cancelar', 'voltar'];
const txt = (c.kind === 'text') ? String(c.text || '').trim().toLowerCase() : '';
let decision = 'proceed';
let reason = '';
if (c.kind === 'flow_complete') {
  const incoming = (c.flowResponse && c.flowResponse.flow_token) || '';
  const last = context.last_flow_token || '';
  if (last && incoming && incoming !== last && idle <= TTL) { decision = 'blocked'; reason = 'flow_stale'; }
} else if (state === 'IDLE') {
  decision = 'proceed';
} else if (c.kind === 'text') {
  if (RESET.indexOf(txt) !== -1) decision = 'proceed';
  else { decision = 'blocked'; reason = 'text_offflow'; }
} else if (c.kind === 'button') {
  const GLOBAL = ['novo_pedido', 'falar_atendente', 'menu'];
  const isGlobal = GLOBAL.indexOf(c.buttonId) !== -1 || String(c.buttonId).indexOf('status:') === 0;
  if (validActions.indexOf(c.buttonId) !== -1 || isGlobal) decision = 'proceed';
  else { decision = 'blocked'; reason = 'button_stale'; }
} else {
  decision = 'blocked'; reason = 'unknown';
}
return [{ json: { decision, reason, effectiveState: state, validActions, context, idle } }];

const c = $('Classificar Mensagem').first().json;
const g = $('Guarda de Contexto').first().json;
const reason = g.reason;
const NL = String.fromCharCode(10);
let actions = Array.isArray(g.validActions) ? g.validActions.slice() : [];
const TITLES = { novo_pedido: 'Fazer novo pedido', falar_atendente: 'Falar c/ atendente' };
const titleFor = (id) => (String(id).indexOf('status:') === 0 ? 'Acompanhar pedido' : (TITLES[id] || String(id)));
let body;
if (reason === 'flow_stale') {
  body = 'Esse pedido ficou aberto tempo demais e expirou ⏳' + NL + NL + 'Toque numa opção abaixo para continuar 👇';
  actions = ['novo_pedido', 'falar_atendente'];
} else if (reason === 'button_stale') {
  body = 'Esse botão já não está mais disponível 🙏' + NL + NL + 'Use uma das opções atuais 👇';
  if (!actions.length) actions = ['novo_pedido', 'falar_atendente'];
} else if (reason === 'text_offflow') {
  body = 'Pra não se perder, é só tocar numa opção 👇' + NL + 'Não precisa digitar — use os botões. (ou mande "menu" para recomeçar)';
  if (!actions.length) actions = ['novo_pedido', 'falar_atendente'];
} else {
  body = 'Escolha uma das opções abaixo 👇';
  if (!actions.length) actions = ['novo_pedido', 'falar_atendente'];
}
const openId = (g.context && g.context.open_order_id) ? g.context.open_order_id : '';
const accepted = !!(g.context && g.context.order_accepted);
const _set = [];
if (openId) _set.push('status:' + openId);
_set.push('novo_pedido');
