const item = $input.first().json;
const c = $('Classificar Mensagem').first().json;
const payload = item.payload;
const phoneNumberId = item.phoneNumberId;
let prev = {};
try { prev = $('Sessão Claim').first().json || {}; } catch (e) { prev = {}; }
let prevContext = prev.context;
if (typeof prevContext === 'string') { try { prevContext = JSON.parse(prevContext); } catch (e) { prevContext = {}; } }
if (!prevContext || typeof prevContext !== 'object') prevContext = {};
let state = 'IDLE';
let validActions = [];
let context = Object.assign({}, prevContext);
const hint = item.session || null;
if (payload && payload.type === 'interactive' && payload.interactive && payload.interactive.type === 'flow') {
  state = 'FLOW_OPEN';
  validActions = [];
  const params = (payload.interactive.action && payload.interactive.action.parameters) || {};
  if (params.flow_token) context.last_flow_token = params.flow_token;
  if (item.followup && item.followup.interactive && item.followup.interactive.action) {
    const fb = item.followup.interactive.action.buttons || [];
    validActions = fb.map((b) => (b.reply && b.reply.id)).filter(Boolean);
  }
} else if (payload && payload.type === 'interactive' && payload.interactive && payload.interactive.type === 'button') {
  const btns = (payload.interactive.action && payload.interactive.action.buttons) || [];
  validActions = btns.map((b) => (b.reply && b.reply.id)).filter(Boolean);
  state = (hint && hint.state) || 'MENU';
} else {
  state = (hint && hint.state) || prev.state || 'IDLE';
  validActions = (hint && hint.valid_actions) || [];
}
