const Q = (s) => "'" + String(s == null ? '' : s).split("'").join("''") + "'";
const saveSql = 'UPDATE wa_session SET state = ' + Q(state) + ', valid_actions = ' + Q(JSON.stringify(validActions)) + '::jsonb, context = ' + Q(JSON.stringify(context)) + '::jsonb, updated_at = now() WHERE channel_id = ' + Q(String(c.phoneNumberId)) + ' AND phone = ' + Q(String(c.phone)) + ';';
